import { useState, useEffect } from "react";
import Login from "./components/Login";
import ListadoIncidencias from "./components/ListadoIncidencias";
import FormularioIncidencias from "./components/FormularioIncidencias";

const LOGIN_API_URL = "http://localhost:3004/login";

function App() {
  const [usuarioLogueado, setUsuarioLogueado] = useState(null);

  // Recuperar sesión al cargar
  useEffect(() => {
    const guardado = localStorage.getItem("usuarioLogueado");
    if (guardado) {
      setUsuarioLogueado(JSON.parse(guardado));
    }
  }, []);

  const onLogin = async (email, password) => {
    const response = await fetch(LOGIN_API_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email, password }),
    });

    if (response.ok) {
      const data = await response.json();
      setUsuarioLogueado(data.user);
      localStorage.setItem("usuarioLogueado", JSON.stringify(data.user));
    } else {
      const errorData = await response.json();
      alert(`Fallo de autenticación. Error: ${response.status}: ${errorData}`);
    }
  };

  return (
    <>
      {!usuarioLogueado ? (
        <aside>
          <Login onLogin={onLogin} />
        </aside>
      ) : (
        <>
          <main>
            <ListadoIncidencias />
          </main>

          <aside>
            <FormularioIncidencias />
          </aside>
        </>
      )}
    </>
  );
}

export default App;
